'use strict';

/* =================== 4  FREIMACHEN & LAGER =================== */
const LOS=Lg('Loslager','Roller support'),FEST=Lg('Festlager','Pin support'),EIN=Lg('Feste Einspannung','Fixed support (clamped)');
